receipts=[]
for p in sorted((L/'outputs').glob('fetch-*-*.json')):receipts+=json.loads(p.read_text())
out={}
for i in json.loads((L/'reservation.json').read_text())['ids']:
 v=E[str(i)];r=v['record'];status,depth,attempt,gap=facts[i]
 abs=(L/f'sources/{i}.abs').read_text()
 versions=re.findall(r'arXiv:[0-9.]+v[0-9]+',abs)
 out[str(i)]=dict(mathdb_id=i,title=r['title'],outcome=status,candidate=False,accepted=False,credit=0,literal_statement=r['statement'],
 provenance={k:v[k] for k in ['chunk','line_1based','chunk_sha256','raw_sha256']},
 statement_sha256=hashlib.sha256(r['statement'].encode()).hexdigest(),raw_file=f'raw/{i}.jsonl',
 source_url=r['source_url'],served_current_version=versions[0] if versions else 'See abs history',source_receipts=[x for x in receipts if x['id']==i],
 review_depth=depth,mathematical_attempts=attempt,remaining_lemma_or_gap=gap,
 historical_check='Read campaign, batch and inherited family snapshots; bounded exact-ID scan of prior Markdown/results paths found no substantive previous assigned-ID disposition. Hash substrings in matched paths were false positives. Not a global nonreview assertion.',
 registry_check='Live HEAD receipts and complete nontruncated OpenAI preprints / Omega D5 and Problems path screens retained. Path screen is not all-proof semantic review.',
 limitations=['No independent novelty clearance or root acceptance','Numerical diagnostics are not Lean proofs','Current source body inspected at named sections; not every citation or every historical arXiv body read'])
assert len(out)==20 and set(out)==set(E)
(L/'results.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
manifest={str(p.relative_to(L)):hashlib.sha256(p.read_bytes()).hexdigest() for p in L.rglob('*') if p.is_file() and p.name!='manifest.json'}
(L/'outputs/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps(dict(entries=len(out),source_exclusions=sum(v['outcome'].startswith('excluded') for v in out.values()),candidates=0,accepted=0),indent=2))
